import java.util.function.BiFunction;
import java.util.function.Function;

public class CurryKitTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object guard(java.util.concurrent.Callable<Object> body) {
        try {
            return body.call();
        } catch (Exception e) {
            return "<threw " + e.getClass().getSimpleName() + ">";
        }
    }

    public static void main(String[] args) {
        BiFunction<Integer, Integer, Integer> add = (a, b) -> a + b;
        BiFunction<String, Integer, String> repeat = (s, n) -> s.repeat(n);

        check("curry(add).apply(2).apply(3)", 5,
                guard(() -> CurryKit.curry(add).apply(2).apply(3)));
        check("curry(repeat).apply(\"ab\").apply(3)", "ababab",
                guard(() -> CurryKit.curry(repeat).apply("ab").apply(3)));

        check("uncurry(curry(add)).apply(2, 3)", 5,
                guard(() -> CurryKit.uncurry(CurryKit.curry(add)).apply(2, 3)));
        Function<Integer, Function<Integer, Integer>> curriedMul = a -> b -> a * b;
        check("uncurry(hand-written).apply(4, 6)", 24,
                guard(() -> CurryKit.uncurry(curriedMul).apply(4, 6)));

        Object plusTen = guard(() -> CurryKit.partial(add, 10));
        if (plusTen instanceof Function) {
            @SuppressWarnings("unchecked")
            Function<Integer, Integer> f = (Function<Integer, Integer>) plusTen;
            check("partial(add, 10).apply(5)", 15, guard(() -> f.apply(5)));
            check("the same partial is reusable", 10, guard(() -> f.apply(0)));
            check("and again", 7, guard(() -> f.apply(-3)));
        } else {
            check("partial(add, 10) returns a Function", "a Function", plusTen);
            failures += 2;
        }

        check("partial(repeat, \"-\").apply(4)", "----",
                guard(() -> CurryKit.partial(repeat, "-").apply(4)));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

