import java.util.function.BiFunction;
import java.util.function.Function;

/**
 * TASK: Currying turns a two-argument function into a chain of one-argument
 * functions, so arguments can be supplied one at a time.
 *
 * curry(f)   turns BiFunction<A, B, R> into Function<A, Function<B, R>>.
 *            curry(add).apply(2).apply(3) -> 5
 * uncurry(f) goes back the other way: Function<A, Function<B, R>> into
 *            BiFunction<A, B, R>, so uncurry(curry(add)).apply(2, 3) -> 5.
 * partial(f, a) fixes the FIRST argument and returns the one-argument
 *            function that is still waiting for the second.
 *            partial(add, 10).apply(5) -> 15, and the same partial can be
 *            applied again and again.
 *
 * None of the three may call the wrapped function until the LAST argument
 * arrives -- they only build and return new functions.
 */
public class CurryKit {

    public static <A, B, R> Function<A, Function<B, R>> curry(BiFunction<A, B, R> f) {
        return a -> b -> f.apply(a, b);
    }

    public static <A, B, R> BiFunction<A, B, R> uncurry(Function<A, Function<B, R>> f) {
        return (a, b) -> f.apply(a).apply(b);
    }

    public static <A, B, R> Function<B, R> partial(BiFunction<A, B, R> f, A a) {
        return curry(f).apply(a);
    }
}
